head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 4

 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.gAcptNo;
scwin.gViewerStat = "R"; // 처리시 뷰=P,  조회시 뷰=R,  사후심사 A
scwin.gIsurCd;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gSndlocTpCd;
scwin.gExmptYn; //면제대상여부(bypass)

scwin.gDate;
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gWinTyp = '';
scwin.gDutyYn = js_duty;
scwin.gDutyChrg = js_duty_chrg; // 세션정보 
scwin.gJobTitle = js_jobtitl; // 팀장  : 09,  부서장: 40,  팀원: 03

scwin.vScrenID = 'ULDSTF11200.xml'; //공시처리현황 - 유가 공시부

scwin.search_yn = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetCode = function() {
    $c.stf.showObj(panel_2, false);
    var strDepCd = js_dep_cd.substring(0, 2);
    //alert("strDepCd-->"+strDepCd); 

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 보여준다.
    //if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    //if (js_dep_cd.substring(0,1) == '2'  || js_dep_cd.substring(0,2) == '34' ) {
    if (strDepCd == '24' || strDepCd == '25' || strDepCd == '2B') {
        //24=채권상장, 25=상장심사부, 2B=증권상품
        $c.stf.showObj(panel_2, true);
    } else if (strDepCd == '26' || strDepCd == '34') {
        //공시팀인경우 당번만 보여준다 2013.03.26
        if (scwin.gDepCd == '2610' || scwin.gDepCd == '3410') {
            //공시제도팀의 경우 팀장, 팀원 모두 공시제도팀공시만 볼 수 있다. 20210312 - IT운영팀
            $c.stf.showObj(panel_2, false);
        } else {
            if (scwin.gJobTitle == '09' || scwin.gDutyYn == 'Y' || scwin.gDutyChrg == 'Y') {
                $c.stf.showObj(panel_2, true);
            }
        }
    }

    //2010.03.05 시장조치검증관련 추가
    if (strDepCd == '34') {
        $c.stf.showObj(panel_FNC_COND, true);
    } else if (strDepCd == '26' || strDepCd == '3B') {
        // 유가 또는 코넥스 공시팀일 경우 '분기매출액해당여부', '분기매출액' 항목 표출
        $c.stf.showObj(panel_FNC_COND, false);
        $c.cm.setColumnProp(grd_Grid, "FNC_COND", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "EMBZL", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "REDU_LOSS_RTO_EXCS50PCT_YN", "Show", false);
    } else {
        $c.stf.showObj(panel_FNC_COND, false);
        $c.cm.setColumnProp(grd_Grid, "FNC_COND", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "EMBZL", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "QTR_SALES", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "QTR_SALES_YN", "Show", false);
        $c.cm.setColumnProp(grd_Grid, "REDU_LOSS_RTO_EXCS50PCT_YN", "Show", false);
    }

    //처음엔 전체 체크
    chb_stat_all.setValue(1);
    chb_stat_00.setValue(1);
    chb_stat_02.setValue(1);
    chb_stat_01.setValue(1);
    chb_stat_10.setValue(1);
    chb_stat_20.setValue(1);
    chb_stat_3A.setValue(1);
    chb_stat_3B.setValue(1);
    chb_stat_40.setValue(1);
    chb_reg.setValue(1);

    //처음엔 전체 체크
    chb_affstat_all.setValue(1);
    chb_affstat_00.setValue(1);
    chb_affstat_01.setValue(1);
    chb_affstat_10.setValue(1);
    chb_affstat_20.setValue(1);
    chb_affstat_30.setValue(1);
    chb_affstat_40.setValue(1);
    if (js_market == "1" || js_market == "2") {
        $c.stf.showObj(panel_MEMO, true);
    } else {
        $c.stf.showObj(panel_MEMO, false);
    }

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_dep.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_emp.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_emp.Reset();

    // 익일전송대상  셋팅
    dts_NxtddTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=NXTDD_TDD_TP_CD";
    dts_NxtddTp.Reset();
};
scwin.fn_SetCode = function() {
    //gDate = getObjectValue(edt_SrchDay) ;		
    // 현재날짜 셋팅			
    edt_SrchDay.setValue($c.ut.cGetToday("yyyymmdd"));
    scwin.gDate = $c.stf.getObjectValue(edt_SrchDay);
};
scwin.fn_DepListLoadComplete = function() {
    $c.stf.setObjectValue(cmb_TeamList, js_dep_cd);
    // 부서코드 가져온후에  초기검색
    scwin.fn_InitSearch();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시처리현황--;
클릭-- > function(pReload) {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_SrchDay).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_SrchDay.focus();
        return;
    }
    var vStatCnt = 0;
    if (chb_stat_00.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_02.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_01.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_10.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_20.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_3A.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_3B.checked == true) {
        vStatCnt++;
    }
    if (chb_stat_40.checked == true) {
        vStatCnt++;
    }
    if (chb_reg.checked == true) {
        vStatCnt++;
    }
    var vAffStatCnt = 0;
    if (chb_affstat_00.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_01.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_10.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_20.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_30.checked == true) {
        vAffStatCnt++;
    }
    if (chb_affstat_40.checked == true) {
        vAffStatCnt++;
    }

    // 처리상태 1개 이상 체크
    if (vStatCnt < 1 && vAffStatCnt < 1) {
        $c.win.alert("처리현황 또는 사후심사현황을 한개 이상  선택하십시요.");
        return;
    }
    scwin.gDate = $c.stf.getObjectValue(edt_SrchDay);

    // 유가 공시팀(26**), 코스닥 공시팀(34**) =>  선택부서로
    //if (js_dep_cd.substring(0,2) == '26'  || js_dep_cd.substring(0,2) == '34' ) {
    if (js_dep_cd.substring(0, 1) == '2' || js_dep_cd.substring(0, 2) == '34') {
        scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
        scwin.gEmpNo = $c.stf.getObjectValue(cmb_EmpList);
    } else {
        scwin.gDepCd = ""; // 부서코드 없음 => 전체	
        scwin.gEmpNo = "";
    }
    fn_Search(pReload);
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !공시처리현황--;
클릭-- > function(pReload) {
    $c.cm.ShowWin_yn(grd_Grid, scwin.search_yn);


    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
    ******************************************************************/
    if (js_bond_yn == "Y") {
        scwin.gLdMktTp = "4";
    }
    txb_TotalCnt.setValue("총  건");
    var url_list = "/DisclosureStudyAffact.do?method=listDisclosureStatusAffact&inputMessageId=DSCLSTATUSCOND_AFF_IN" + "&outputMessageId=DSCLSTATUSLIST_AFF_OUT";
    var url_cond = "&ACPT_DATE=" + scwin.gDate + "&DEP_CD=" + scwin.gDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LD_MKT_TP=" + scwin.gLdMktTp + "&STAT_00=" + scwin.getChkValue(chb_stat_00) + "&STAT_02=" + scwin.getChkValue(chb_stat_02) + "&STAT_01=" + scwin.getChkValue(chb_stat_01) + "&STAT_10=" + scwin.getChkValue(chb_stat_10) + "&STAT_20=" + scwin.getChkValue(chb_stat_20) + "&STAT_3A=" + scwin.getChkValue(chb_stat_3A) + "&STAT_3B=" + scwin.getChkValue(chb_stat_3B) + "&STAT_40=" + scwin.getChkValue(chb_stat_40) + "&STAT_REG=" + scwin.getChkValue(chb_reg) + "&ISUR_NM_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&NXTDD_TP=" + $c.stf.getObjectValue(cmb_NxtddTp) + "&SECT_TP=" + $c.stf.getObjectValue(cmb_SectTp) + "&UP_DEP_CD=" + js_belngdepcd + "&FNC_COND=" + scwin.getChkValue(chk_FNC_COND) + "&AFF_STAT_00=" + scwin.getChkValue(chb_affstat_00) + "&AFF_STAT_01=" + scwin.getChkValue(chb_affstat_01) + "&AFF_STAT_10=" + scwin.getChkValue(chb_affstat_10) + "&AFF_STAT_20=" + scwin.getChkValue(chb_affstat_20) + "&AFF_STAT_30=" + scwin.getChkValue(chb_affstat_30) + "&AFF_STAT_40=" + scwin.getChkValue(chb_affstat_40);

    /*var url_count = "/DisclosureStatus.do?method=countDisclosureStatus&inputMessageId=DSCLSTATUSCOND_IN"
    		+ "&outputMessageId=DSCLSTATUSCNT_OUT" 
    		+ "&ACPT_DATE=" + gDate
    		+ "&DEP_CD=" + gDepCd
    		+ "&EMP_NO=" + gEmpNo
    		+ "&LD_MKT_TP=" + gLdMktTp
    		+ "&STAT_00="  + getChkValue(chb_stat_00)
    		+ "&STAT_02="  + getChkValue(chb_stat_02)
    		+ "&STAT_01="  + getChkValue(chb_stat_01)
    		+ "&STAT_10="  + getChkValue(chb_stat_10)			
    		+ "&STAT_20="  + getChkValue(chb_stat_20)
    		+ "&STAT_3A="  + getChkValue(chb_stat_3A)
    		+ "&STAT_3B="  + getChkValue(chb_stat_3B)
    		+ "&STAT_40="  + getChkValue(chb_stat_40)
    		+ "&STAT_REG="  + getChkValue(chb_reg)
    		+ "&ISUR_NM_CD="+ getObjectValue(txb_isur_cd)
    		+ "&NXTDD_TP="+ getObjectValue(cmb_NxtddTp)
    		+ "&SECT_TP="+ getObjectValue(cmb_SectTp)
    		+ "&UP_DEP_CD="  + js_belngdepcd
    		+ "&FNC_COND="+ getChkValue(chk_FNC_COND);
    */

    //alert('[pReload]'+pReload);

    var url_log = '';
    if (pReload != 'Y') {
        //자동refresh일때는 로그 없앰
        url_log = "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    }

    // 그리드의 데이타 조회
    dts_DsclStatusList.DataID = encodeURI(url_list + url_cond + url_log);
    dts_DsclStatusList.reset();

    // 처리상태별 건수
    //dts_DsclStatusCnt.DataID = encodeURI(url_count);
    //dts_DsclStatusCnt.reset();	

};








// 그리드에서 클릭 row의 변수셋팅
scwin.fn_setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclStatusList.getCellData(eval(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclStatusList.getCellData(eval(obj), "FORM_CD");
    scwin.gIsurCd = dts_DsclStatusList.getCellData(eval(obj), "ISUR_CD");
    scwin.gExmptYn = dts_DsclStatusList.getCellData(eval(obj), "EXMPT_OBJ_DISCLS_YN"); //bypass 여부 

};



// 화면 로딩시 디폴트 검색
scwin.fn_InitSearch = function() {
    //fn_Search();		
    scwin.fn_Reload('N');
};
scwin.fn_Reload = function(pReload) {
    fn_CheckCond(pReload);
    setTimeout("fn_Reload('Y')", 30000); // 1초 = 1000 , 30초 = 30000

};
scwin.fn_checkAll = function() {
    // 전체가 체크일때 
    if (chb_stat_all.checked == true) {
        chb_stat_00.setValue(1);
        chb_stat_02.setValue(1);
        chb_stat_01.setValue(1);
        chb_stat_10.setValue(1);
        chb_stat_20.setValue(1);
        chb_stat_3A.setValue(1);
        chb_stat_3B.setValue(1);
        chb_stat_40.setValue(1);
        chb_reg.setValue(1);
    } else {
        chb_stat_00.setValue(0);
        chb_stat_02.setValue(0);
        chb_stat_01.setValue(0);
        chb_stat_10.setValue(0);
        chb_stat_20.setValue(0);
        chb_stat_3A.setValue(0);
        chb_stat_3B.setValue(0);
        chb_stat_40.setValue(0);
        chb_reg.setValue(0);
    }
};



//처리현황(전체)
scwin.fn_checkAll2 = function() {
    // 전체가 체크일때 
    if (chb_affstat_all.checked == true) {
        chb_affstat_00.setValue(1);
        chb_affstat_01.setValue(1);
        chb_affstat_10.setValue(1);
        chb_affstat_20.setValue(1);
        chb_affstat_30.setValue(1);
        chb_affstat_40.setValue(1);
    } else {
        chb_affstat_00.setValue(0);
        chb_affstat_01.setValue(0);
        chb_affstat_10.setValue(0);
        chb_affstat_20.setValue(0);
        chb_affstat_30.setValue(0);
        chb_affstat_40.setValue(0);
    }
};
scwin.fn_PopupFncInfo = async function() {
    var url = "/dsclproc/ULDSTF10201.gfm?" + "gAcptNo=" + scwin.gAcptNo + "&gMainFormCd=" + scwin.gMainFormCd + "&gWinTyp=" + scwin.gWinTyp + "&frameID=" + frame.FrameID;
    var winTitle = "실질심사 상세";
    if ($c.frame.path("/top") != undefined) {
        $c.frame.path("/top").WinOpen("ULDSTF10201" + scwin.gAcptNo, url, winTitle, 1000, 745 + 30);
    } else {
        await $c.frame.CreateFrame("ULDSTF10201" + scwin.gAcptNo, "/dsclproc/ULDSTF10201.gfm", winTitle, 200, 5, 875, 745 + 30, "window", 0, 0, true);
    }
};
scwin.fn_PopupSaleInfo = async function() {
    var url = "/dsclproc/ULDSTF10202.gfm?" + "gAcptNo=" + scwin.gAcptNo + "&gMainFormCd=" + scwin.gMainFormCd + "&gWinTyp=" + scwin.gWinTyp + "&frameID=" + frame.FrameID;
    var winTitle = "분기매출액 상세";
    if ($c.frame.path("/top") != undefined) {
        $c.frame.path("/top").WinOpen("ULDSTF10202" + scwin.gAcptNo, url, winTitle, 875, 440 + 30);
    } else {
        await $c.frame.CreateFrame("ULDSTF10201" + scwin.gAcptNo, "/dsclproc/ULDSTF10202.gfm", winTitle, 200, 5, 875, 440 + 30, "window", 0, 0, true);
    }
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.fn_setContnId(row);
    if (colid == "DOC_TITLE") {
        $c.stf.fn_OpenNoDisclViewer(scwin.gAcptNo, scwin.gViewerStat, js_emp_no, js_dep_cd, js_jobtitl, js_duty, js_duty_chrg, 'S', dts_DutyStatus); //2013.05.14
        //fn_OpenNoDisclViewer(gAcptNo, gViewerStat);

    } else if (colid == "ACPT_DDTM") {
        $c.stf.fn_OpenDisclAllList();
    } else if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "FNC_COND" && dts_DsclStatusList.getCellData(row, "FNC_COND") != '') {
        scwin.gWinTyp = '1';
        scwin.fn_PopupFncInfo();
    } else if (colid == "EMBZL" && dts_DsclStatusList.getCellData(row, "EMBZL") != '') {
        scwin.gWinTyp = '2';
        scwin.fn_PopupFncInfo();
    } else if (colid == "REDU_LOSS_RTO_EXCS50PCT_YN" && dts_DsclStatusList.getCellData(row, "REDU_LOSS_RTO_EXCS50PCT_YN") != '') {
        scwin.gWinTyp = '2';
        scwin.fn_PopupFncInfo();
    } else if (colid == "QTR_SALES_YN" && dts_DsclStatusList.getCellData(row, "QTR_SALES_YN") != '' && dts_DsclStatusList.getCellData(row, "QTR_SALES_YN") != '미추출') {
        scwin.fn_PopupSaleInfo();
    }
};
scwin.btn_Search_onclick = function() {
    scwin.search_yn = true;
    fn_CheckCond('N');
};
scwin.dts_dep_OnLoadError = function() {
    $c.stf.alert_error(dts_dep);
};
scwin.dts_DutyStatus_OnLoadError = function() {
    $c.stf.alert_error(dts_DutyStatus);
};
scwin.dts_emp_OnLoadError = function() {
    $c.stf.alert_error(dts_emp);
};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    /******************************************************************
    	2009.09.01 채권공시관련 - 채권상장팀이면 시장구분을 '4'로 셋팅
    ******************************************************************/
    /*
    if(js_bond_yn == "Y"){
    	setObjectValue(cmb_TeamList, js_dep_cd) ;		//채권상장팀으로 셋팅
    }else{
    	setObjectValue(cmb_TeamList, js_dep_cd) ;		// 로그인사용자의 팀이 디폴트일때
    }
    */

    scwin.fn_DepListLoadComplete();
